(5160011, 751316, 54645, '<td valign="top">I like the pose, but I get the sense the WB is off and the background is distracting rather than complementing. I like the use of the pipe and his smile.</td>', 'I like the pose, but I get the sense the WB is off and the background is distracting rather than complementing. I like the use of the pipe and his smile.', '2008-12-31 13:08:34.000000', NULL, 1),
(5160107, 751090, 60865, '<td valign="top">i want to look like you when im 70.</td>', 'i want to look like you when im 70.', '2008-12-31 13:37:36.000000', NULL, 1),
