(5161028, 751394, 100831, '<td valign="top">Grandfather has very good teeth!</td>', 'Grandfather has very good teeth!', '2008-12-31 19:08:59.000000', NULL, 1),
(5161030, 750492, 100831, '<td valign="top">nice street photography. I''m wondering if there could have been a slight bit more contrast.</td>', 'nice street photography. I''m wondering if there could have been a slight bit more contrast.', '2008-12-31 19:09:37.000000', NULL, 1),
(5161031, 750199, 100831, '<td valign="top">he he he. what a hairdo.</td>', 'he he he. what a hairdo.', '2008-12-31 19:10:24.000000', NULL, 1),
(5161032, 750427, 100831, '<td valign="top">Right. Next it will be trifocals - maybe the kind with no lines.</td>', 'Right. Next it will be trifocals - maybe the kind with no lines.', '2008-12-31 19:11:24.000000', NULL, 1),
(5161035, 750529, 100831, '<td valign="top">Nicely done. Great display of affection.</td>', 'Nicely done. Great display of affection.', '2008-12-31 19:12:33.000000', NULL, 1),
(5161036, 751415, 100831, '<td valign="top">I hope the rest of him is sprightly too! He looks like a man I''d enjoy a conversation with.</td>', 'I hope the rest of him is sprightly too! He looks like a man I''d enjoy a conversation with.', '2008-12-31 19:13:44.000000', NULL, 1),
(5161038, 751423, 100831, '<td valign="top">95! She looks great!!</td>', '95! She looks great!!', '2008-12-31 19:14:11.000000', NULL, 1),
(5161040, 750105, 100831, '<td valign="top">Nicely framed and composed.</td>', 'Nicely framed and composed.', '2008-12-31 19:14:37.000000', NULL, 1),
(5161041, 751223, 100831, '<td valign="top">I''m not sure about the elderly portrait part but the kid is adorable!</td>', 'I''m not sure about the elderly portrait part but the kid is adorable!', '2008-12-31 19:15:23.000000', NULL, 1),
(5161043, 751165, 100831, '<td valign="top">Colorful woman! Lucky you.</td>', 'Colorful woman! Lucky you.', '2008-12-31 19:15:45.000000', NULL, 1),
(5161046, 750491, 100831, '<td valign="top">...they often go together.</td>', '...they often go together.', '2008-12-31 19:16:10.000000', NULL, 1),
(5161048, 750934, 100831, '<td valign="top">Keep it up, Dad! You''re looking great.</td>', 'Keep it up, Dad! You''re looking great.', '2008-12-31 19:17:15.000000', NULL, 1),
(5161063, 750207, 47091, '<td valign="top">I like the photo I believe the back ground could have been better</td>', 'I like the photo I believe the back ground could have been better', '2008-12-31 19:38:34.000000', NULL, 1),
(5161067, 751440, 47091, '<td valign="top">I like it great shot</td>', 'I like it great shot', '2008-12-31 19:42:23.000000', NULL, 1),
(5161074, 750145, 47091, '<td valign="top">Looks a little over exposed you may have intended it that way.</td>', 'Looks a little over exposed you may have intended it that way.', '2008-12-31 19:47:44.000000', NULL, 1),
(5161075, 750009, 47091, '<td valign="top">awesome love the colors</td>', 'awesome love the colors', '2008-12-31 19:48:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5161076, 751380, 47091, '<td valign="top">I like it</td>', 'I like it', '2008-12-31 19:49:43.000000', NULL, 1),
(5161082, 750934, 47091, '<td valign="top">great photo and what a golfer</td>', 'great photo and what a golfer', '2008-12-31 19:56:54.000000', NULL, 1),
(5161083, 750675, 47091, '<td valign="top">I bet the leather bed sticks to your skin.</td>', 'I bet the leather bed sticks to your skin.', '2008-12-31 19:58:09.000000', NULL, 1),
(5161084, 751203, 47091, '<td valign="top">Great catch</td>', 'Great catch', '2008-12-31 19:58:41.000000', NULL, 1),
(5161102, 750108, 47091, '<td valign="top">The rest of the room is a distraction to me it keeps drawing my eyes away from her.</td>', 'The rest of the room is a distraction to me it keeps drawing my eyes away from her.', '2008-12-31 20:08:12.000000', NULL, 1),
(5161246, 750199, 24846, '<td valign="top">Jerry Garcia Lives! Like the tilt of the glasses and look in his eey. Like the tight crop from his left as well as bw. A favorite. Good luck and HNY! -9-</td>', 'Jerry Garcia Lives! Like the tilt of the glasses and look in his eey. Like the tight crop from his left as well as bw. A favorite. Good luck and HNY! -9-', '2008-12-31 21:39:58.000000', NULL, 1),
(5161248, 751086, 24846, '<td valign="top">Nice smild</td>', 'Nice smild', '2008-12-31 21:40:27.000000', NULL, 1),
(5161249, 751128, 24846, '<td valign="top">Nice lighting.  Conveys a "don''t mess with me look"</td>', 'Nice lighting.  Conveys a "don''t mess with me look"', '2008-12-31 21:41:56.000000', NULL, 1),
(5161256, 751347, 24846, '<td valign="top">Nice crop and pp, emotive. Sorry about the PD.</td>', 'Nice crop and pp, emotive. Sorry about the PD.', '2008-12-31 21:45:00.000000', NULL, 1),
(5161260, 751551, 24846, '<td valign="top">Great lighting (no lens glare) colors are soothing especially blue sky with sweater. Nice skin tones. Hair to her left a bit distracting. -9-</td>', 'Great lighting (no lens glare) colors are soothing especially blue sky with sweater. Nice skin tones. Hair to her left a bit distracting. -9-', '2008-12-31 21:47:53.000000', NULL, 1),
(5161265, 751335, 24846, '<td valign="top">Nice. A storyteller I can see. -9-</td>', 'Nice. A storyteller I can see. -9-', '2008-12-31 21:49:08.000000', NULL, 1),
(5161266, 751530, 24846, '<td valign="top">BROWN</td>', 'BROWN', '2008-12-31 21:49:48.000000', NULL, 1),
(5161270, 751415, 24846, '<td valign="top">Nice pov, little soft in eyes, poor speller.</td>', 'Nice pov, little soft in eyes, poor speller.', '2008-12-31 21:51:27.000000', NULL, 1),
(5161277, 749908, 24846, '<td valign="top">Here''s a Pharaoh. -10-</td>', 'Here''s a Pharaoh. -10-', '2008-12-31 21:53:09.000000', NULL, 1),
(5161305, 751316, 99394, '<td valign="top">Would have really liked to see this in B&amp;W</td>', 'Would have really liked to see this in B&W', '2008-12-31 22:03:15.000000', NULL, 1),
(5161308, 750329, 101117, '<td valign="top">Good shot, particularly like the blown out background contrasting against the wood, which frames the subject nicely. My only complaint is that there''s a little too much shadow in the mans face, perhaps a reflector to just add a touch more light while maintaining the overall look would have been good.</td>', 'Good shot, particularly like the blown out background contrasting against the wood, which frames the subject nicely. My only complaint is that there''s a little too much shadow in the mans face, perhaps a reflector to just add a touch more light while maintaining the overall look would have been good.', '2008-12-31 22:07:00.000000', NULL, 1),
(5161316, 751089, 98171, '<td valign="top">she is beautiful...</td>', 'she is beautiful...', '2008-12-31 22:12:43.000000', NULL, 1),
(5161317, 750675, 101117, '<td valign="top">This is great, it just perfectly represents Christmas day to me after all the food and drink! If it was my family I would give him 10 minutes and he would be snoring! 8</td>', 'This is great, it just perfectly represents Christmas day to me after all the food and drink! If it was my family I would give him 10 minutes and he would be snoring! 8', '2008-12-31 22:12:47.000000', NULL, 1),
(5161332, 750013, 101117, '<td valign="top">I understand the idea here, but I feel you have failed in the composition. As a shot to simply record the item it doesn''t work as the angles are wrong and the background is distracting. As taken to make it an attractive scene, the centred composition doesn''t work and the water is slightly out of focus.</td>', 'I understand the idea here, but I feel you have failed in the composition. As a shot to simply record the item it doesn''t work as the angles are wrong and the background is distracting. As taken to make it an attractive scene, the centred composition doesn''t work and the water is slightly out of focus.', '2008-12-31 22:18:04.000000', NULL, 1),
(5161341, 751347, 101117, '<td valign="top">Very striking shot. There''s something a little off about it though, it has a softness which doesn''t quite look right. I think the softness in this image is a good approach, but for some reason here it looks like you have one picture overlaid on top of another, but very slightly offset.</td>', 'Very striking shot. There''s something a little off about it though, it has a softness which doesn''t quite look right. I think the softness in this image is a good approach, but for some reason here it looks like you have one picture overlaid on top of another, but very slightly offset.', '2008-12-31 22:21:50.000000', NULL, 1),
(5161347, 750532, 101117, '<td valign="top">Nice shot, coming from Scotland I know how tough this time of year winter can be on the elderly! With this shot I think the fill flash has separated the indoor scene from the outdoor scene and made it look more like an abstract view of the snow rather than something with real impact.</td>', 'Nice shot, coming from Scotland I know how tough this time of year winter can be on the elderly! With this shot I think the fill flash has separated the indoor scene from the outdoor scene and made it look more like an abstract view of the snow rather than something with real impact.', '2008-12-31 22:25:47.000000', NULL, 1),
(5161351, 750106, 101117, '<td valign="top">Feels a little out of focus and the frame of the glasses is slightly obscuring the closest eye. The light area in the background is also a touch distracting, raising the height of the camera and looking downwards a touch more would have solved a couple of these problems.</td>', 'Feels a little out of focus and the frame of the glasses is slightly obscuring the closest eye. The light area in the background is also a touch distracting, raising the height of the camera and looking downwards a touch more would have solved a couple of these problems.', '2008-12-31 22:30:05.000000', NULL, 1),
(5161352, 750145, 101968, '<td valign="top">Terrific image. A very nice use of areas of subtle over-exposure.  This is just the kind of b&amp;w portraiture that I like. Well done!</td>', 'Terrific image. A very nice use of areas of subtle over-exposure.  This is just the kind of b&w portraiture that I like. Well done!', '2008-12-31 22:30:15.000000', NULL, 1),
(5161355, 751394, 101117, '<td valign="top">Like the expression here, it conveys a warmth typical to grandparents. The crop feels a little tight though.</td>', 'Like the expression here, it conveys a warmth typical to grandparents. The crop feels a little tight though.', '2008-12-31 22:32:08.000000', NULL, 1),
(5161356, 751305, 101968, '<td valign="top">I was thinking of doing something like this. Very well done, nice interpretation.</td>', 'I was thinking of doing something like this. Very well done, nice interpretation.', '2008-12-31 22:32:21.000000', NULL, 1),
(5161357, 751090, 101117, '<td valign="top">Nice self portrait, I always find these difficult running back and forwards trying to get the lighting and focus right!</td>', 'Nice self portrait, I always find these difficult running back and forwards trying to get the lighting and focus right!', '2008-12-31 22:33:57.000000', NULL, 1),
(5161358, 750886, 101968, '<td valign="top">Great expression!</td>', 'Great expression!', '2008-12-31 22:34:05.000000', NULL, 1),
(5161367, 751203, 101117, '<td valign="top">Very well composed portrait, great lighting and the black back background isolates the subjects nicely. 9</td>', 'Very well composed portrait, great lighting and the black back background isolates the subjects nicely. 9', '2008-12-31 22:43:09.000000', NULL, 1),
(5161369, 750009, 101117, '<td valign="top">Nice portrait, great detail and expression.</td>', 'Nice portrait, great detail and expression.', '2008-12-31 22:43:52.000000', NULL, 1),
(5161370, 751305, 101117, '<td valign="top">Very nice shot, love the alternative take on the theme. Great detail in foreground and background. 9</td>', 'Very nice shot, love the alternative take on the theme. Great detail in foreground and background. 9', '2008-12-31 22:44:55.000000', NULL, 1),
(5161372, 751011, 101117, '<td valign="top">Good portrait and use of B&amp;W, I think there''s a little too much in the frame though. Perhaps removing a little off both sides and having more of a portrait aspect ratio would be good.</td>', 'Good portrait and use of B&W, I think there''s a little too much in the frame though. Perhaps removing a little off both sides and having more of a portrait aspect ratio would be good.', '2008-12-31 22:46:25.000000', NULL, 1),
(5161378, 751554, 101117, '<td valign="top">Excellent expression, good detail and DOF. I wonder if the background is just a bit too bright though.</td>', 'Excellent expression, good detail and DOF. I wonder if the background is just a bit too bright though.', '2008-12-31 22:50:37.000000', NULL, 1),
(5161382, 751349, 101117, '<td valign="top">Great shot, love the composition and light here and their expressions are great too.</td>', 'Great shot, love the composition and light here and their expressions are great too.', '2008-12-31 22:53:20.000000', NULL, 1),
(5161388, 750455, 101117, '<td valign="top">Nice portrait in a very good setting. The dark areas seem just a little too dark, perhaps just a very slight increase in shadow areas would be good. 8</td>', 'Nice portrait in a very good setting. The dark areas seem just a little too dark, perhaps just a very slight increase in shadow areas would be good. 8', '2008-12-31 23:00:12.000000', NULL, 1),
(5161391, 751495, 101117, '<td valign="top">The direct front on lighting in this shot has made the image look flat and ''passport'' like. A softer light / multiple light sources would have worked better.</td>', 'The direct front on lighting in this shot has made the image look flat and ''passport'' like. A softer light / multiple light sources would have worked better.', '2008-12-31 23:02:43.000000', NULL, 1),
(5161803, 751437, 69325, '<td valign="top">you seem to have hit all the points of the "compass" of <strike>good</strike> great photography on this one. A great looking model with lots of character. something more than just staring at the camera. a crisp b&amp;w conversion and a dof that really gives it some punch. excellent work. i have an entry in this challenge but unlike a lot of people i have no problem voting in an unbiased manner, because i love photography. i fully expect to see this on the front page. /10</td>', 'you seem to have hit all the points of the "compass" of good great photography on this one. A great looking model with lots of character. something more than just staring at the camera. a crisp b&w conversion and a dof that really gives it some punch. excellent work. i have an entry in this challenge but unlike a lot of people i have no problem voting in an unbiased manner, because i love photography. i fully expect to see this on the front page. /10', '2009-01-01 02:38:04.000000', NULL, 1),
(5161848, 750427, 30244, '<td valign="top">I think it would have been better without the flash shaddow</td>', 'I think it would have been better without the flash shaddow', '2009-01-01 03:50:48.000000', NULL, 1),
(5161959, 751551, 37858, '<td valign="top">Nice looking woman.  She even looks wise.  Well photographed. My favorite. 9</td>', 'Nice looking woman.  She even looks wise.  Well photographed. My favorite. 9', '2009-01-01 06:11:40.000000', NULL, 1),
(5162043, 751291, 78088, '<td valign="top">thats a lovely pic</td>', 'thats a lovely pic', '2009-01-01 08:07:38.000000', NULL, 1),
(5162045, 750108, 78088, '<td valign="top">thats a really cool port................10</td>', 'thats a really cool port................10', '2009-01-01 08:12:01.000000', NULL, 1),
(5162046, 751125, 78088, '<td valign="top">god bless</td>', 'god bless', '2009-01-01 08:12:22.000000', NULL, 1),
(5162047, 751551, 78088, '<td valign="top">10........the blue rocks...</td>', '10........the blue rocks...', '2009-01-01 08:13:48.000000', NULL, 1),
(5162057, 751335, 73250, '<td valign="top">I really like this shot. It''s a great environmental photo...the background and the glass tell you where he is and his eyes engage you fully. The sepia adds to the feel of it, as well.</td>', 'I really like this shot. It''s a great environmental photo...the background and the glass tell you where he is and his eyes engage you fully. The sepia adds to the feel of it, as well.', '2009-01-01 08:24:25.000000', NULL, 1),
(5162063, 751381, 73250, '<td valign="top">Nicely done...you did well to give us a feel for this gentleman. The background helps to tell the story. I like the angle and the smoke adds to the interest.</td>', 'Nicely done...you did well to give us a feel for this gentleman. The background helps to tell the story. I like the angle and the smoke adds to the interest.', '2009-01-01 08:28:17.000000', NULL, 1),
(5162068, 751420, 73250, '<td valign="top">I really like this image. It is so well composed...the lines and framing are perfect!</td>', 'I really like this image. It is so well composed...the lines and framing are perfect!', '2009-01-01 08:30:04.000000', NULL, 1),
(5162103, 751466, 60047, '<td valign="top">I think cropping off the sides to make this more of a square shot would help this shot''s composition. Too bad the infant isn''t looking toward the camera.</td>', 'I think cropping off the sides to make this more of a square shot would help this shot''s composition. Too bad the infant isn''t looking toward the camera.', '2009-01-01 08:42:50.000000', NULL, 1),
(5162125, 750233, 60047, '<td valign="top">Moving the focus to the plane of the eye rather than allowing the focus to land on the the plane of the sweater would have been a better choice in my opinion. This is a great close composition made more interesting due to the position of the hand.</td>', 'Moving the focus to the plane of the eye rather than allowing the focus to land on the the plane of the sweater would have been a better choice in my opinion. This is a great close composition made more interesting due to the position of the hand.', '2009-01-01 08:50:08.000000', NULL, 1),
(5162152, 749888, 60047, '<td valign="top">You''ve helped manage the light well. I think a closer crop would have been a better choice. The star of this shot is the subject, of course. The "best supporting actor" is the umbrella. Trying to include the interesting light on the tree as well as the water below is unnecessary and almost too much - especially for this particular challenge. I would love to see a crop just below the hands and then at the edges of the umbrella.</td>', 'You''ve helped manage the light well. I think a closer crop would have been a better choice. The star of this shot is the subject, of course. The "best supporting actor" is the umbrella. Trying to include the interesting light on the tree as well as the water below is unnecessary and almost too much - especially for this particular challenge. I would love to see a crop just below the hands and then at the edges of the umbrella.', '2009-01-01 08:56:32.000000', NULL, 1),
(5162157, 750491, 60047, '<td valign="top">I really like the way you''ve managed the light. The POV is different - having the subject look up and to her right.Unfortunately the chair and the composition of the rest of the BG detract from this otherwise awesome capture. She looks like a fascinating person to have a conversation with!</td>', 'I really like the way you''ve managed the light. The POV is different - having the subject look up and to her right.Unfortunately the chair and the composition of the rest of the BG detract from this otherwise awesome capture. She looks like a fascinating person to have a conversation with!', '2009-01-01 08:59:21.000000', NULL, 1),
(5162174, 751165, 60047, '<td valign="top">I love her expression and the inclusion of her hand in the composition. The black BG works - but I would prefer less negative space on the left and a closer crop in order to better see the details of her fascinating face.</td>', 'I love her expression and the inclusion of her hand in the composition. The black BG works - but I would prefer less negative space on the left and a closer crop in order to better see the details of her fascinating face.', '2009-01-01 09:03:54.000000', NULL, 1),
(5162181, 750529, 60047, '<td valign="top">What an interesting expression. Good light on this. The BG is a bit distracting and I wish the DOF was shallower to help blur it out more.</td>', 'What an interesting expression. Good light on this. The BG is a bit distracting and I wish the DOF was shallower to help blur it out more.', '2009-01-01 09:06:21.000000', NULL, 1),
(5162188, 751394, 60047, '<td valign="top">Love the tight crop. The DOF seems just a tad shallow since the right side of the shot appears to be in focus more than the left side of the shot.</td>', 'Love the tight crop. The DOF seems just a tad shallow since the right side of the shot appears to be in focus more than the left side of the shot.', '2009-01-01 09:11:10.000000', NULL, 1),
(5162198, 751495, 60047, '<td valign="top">The light seems to be just a bit too harsh and flat on this. I love the colors on this.</td>', 'The light seems to be just a bit too harsh and flat on this. I love the colors on this.', '2009-01-01 09:14:20.000000', NULL, 1),
(5162206, 750106, 60047, '<td valign="top">The leading edge of her glasses is in focus. The rest is less so. I would have tried to place the point of focus on the closer eye. The close up shot is great and the light is well managed. The BG is just a little distracting - not great but not bad, either.</td>', 'The leading edge of her glasses is in focus. The rest is less so. I would have tried to place the point of focus on the closer eye. The close up shot is great and the light is well managed. The BG is just a little distracting - not great but not bad, either.', '2009-01-01 09:17:35.000000', NULL, 1),
(5162216, 751223, 60047, '<td valign="top">The light is a little harsh and flat. The dark BG prevents this from working as a high key shot. Unfortunately the child steals the show away from the Challenge subject - but what a great capture of the child!</td>', 'The light is a little harsh and flat. The dark BG prevents this from working as a high key shot. Unfortunately the child steals the show away from the Challenge subject - but what a great capture of the child!', '2009-01-01 09:22:12.000000', NULL, 1),
(5162226, 750427, 60047, '<td valign="top">Great expression and interesting head position. I think a bit more contrast might do this B&amp;W better. The harsh shadow on the BG is distracting.</td>', 'Great expression and interesting head position. I think a bit more contrast might do this B&W better. The harsh shadow on the BG is distracting.', '2009-01-01 09:28:11.000000', NULL, 1),
(5162232, 750848, 60047, '<td valign="top">What an interesting juxtaposition of the disturbing bruises and his expression of positive confidence. Great capture. Not sure you need all the real estate around him - I would have gone for a closer crop.</td>', 'What an interesting juxtaposition of the disturbing bruises and his expression of positive confidence. Great capture. Not sure you need all the real estate around him - I would have gone for a closer crop.', '2009-01-01 09:31:03.000000', NULL, 1),
(5162234, 750758, 60047, '<td valign="top">The light on her seems just a little harsh. I understand the positioning of her against the BG but something about it isn''t working for me. I am not sure if it is the B&amp;W color tones or the crop being just under her chin.</td>', 'The light on her seems just a little harsh. I understand the positioning of her against the BG but something about it isn''t working for me. I am not sure if it is the B&W color tones or the crop being just under her chin.', '2009-01-01 09:34:33.000000', NULL, 1),
(5162239, 751086, 60047, '<td valign="top">She seems to be just a tad OOF. The lighting is a bit harsh. I love her engaging eyes and warm smile.</td>', 'She seems to be just a tad OOF. The lighting is a bit harsh. I love her engaging eyes and warm smile.', '2009-01-01 09:37:39.000000', NULL, 1),
(5162242, 750886, 60047, '<td valign="top">What a wonderful searching expression. The soft focus works beautifully here. The lighting is just a bit harsh and distracting on her hair - what a tragedy - because this shot has the potential of being a top contender. I also think you could have increased the contrast just a bit and helped this shot. Great capture.</td>', 'What a wonderful searching expression. The soft focus works beautifully here. The lighting is just a bit harsh and distracting on her hair - what a tragedy - because this shot has the potential of being a top contender. I also think you could have increased the contrast just a bit and helped this shot. Great capture.', '2009-01-01 09:41:28.000000', NULL, 1),
(5162244, 751125, 60047, '<td valign="top">Powerful.</td>', 'Powerful.', '2009-01-01 09:42:09.000000', NULL, 1),
(5162249, 751308, 60047, '<td valign="top">The tonal balance on her is perfect. The expression is priceless. I do think that the doll distracts. I feel strongly that this shot without the doll and cropped tighter could have easily been a top contender.</td>', 'The tonal balance on her is perfect. The expression is priceless. I do think that the doll distracts. I feel strongly that this shot without the doll and cropped tighter could have easily been a top contender.', '2009-01-01 09:44:09.000000', NULL, 1),
(5162253, 751539, 60047, '<td valign="top">What a great soft and warm expression. The light appears to be just a bit too harsh and flat.</td>', 'What a great soft and warm expression. The light appears to be just a bit too harsh and flat.', '2009-01-01 09:45:12.000000', NULL, 1),
(5162256, 751089, 60047, '<td valign="top">I love the mischievous expression. The railing in the BG is distracting. The contrast appears to be just a tad too harsh.</td>', 'I love the mischievous expression. The railing in the BG is distracting. The contrast appears to be just a tad too harsh.', '2009-01-01 09:46:40.000000', NULL, 1),
(5162262, 751349, 60047, '<td valign="top">This is really quite a great capture. The focal point appears to be on the seats on the BG rather than on the subjects themselves. This sot is evocative of memories of any parent whose child has played a team sport.</td>', 'This is really quite a great capture. The focal point appears to be on the seats on the BG rather than on the subjects themselves. This sot is evocative of memories of any parent whose child has played a team sport.', '2009-01-01 09:49:20.000000', NULL, 1),
(5162265, 749886, 60047, '<td valign="top">This shot would have been better if you could have moved a bit to the right so the headstone blocking her lower legs was not so distracting.</td>', 'This shot would have been better if you could have moved a bit to the right so the headstone blocking her lower legs was not so distracting.', '2009-01-01 09:50:33.000000', NULL, 1),
(5162268, 750329, 60047, '<td valign="top">I like the idea of the back lighting. I think just a bit more exposure on his face would have worked better - I really want to see more detail on that marvelous expression he happens to have going on.</td>', 'I like the idea of the back lighting. I think just a bit more exposure on his face would have worked better - I really want to see more detail on that marvelous expression he happens to have going on.', '2009-01-01 09:52:08.000000', NULL, 1),
(5162274, 751316, 60047, '<td valign="top">The lighting is just a bit harsh on this. His face appears to be just a bit OOF. I love the use of the arm and the clasping of the pipe.</td>', 'The lighting is just a bit harsh on this. His face appears to be just a bit OOF. I love the use of the arm and the clasping of the pipe.', '2009-01-01 09:53:36.000000', NULL, 1),
(5162283, 751412, 60047, '<td valign="top">I love the idea of this shot. I love her expression and the way her hand is obscuring her face. Your focus is spot on. I think you could crop out the building to the left and the white car on the right and you would have a more interesting composition with more emphasis on the subject.</td>', 'I love the idea of this shot. I love her expression and the way her hand is obscuring her face. Your focus is spot on. I think you could crop out the building to the left and the white car on the right and you would have a more interesting composition with more emphasis on the subject.', '2009-01-01 09:56:51.000000', NULL, 1),
(5162297, 751554, 60047, '<td valign="top">Love the expression and the tight crop. I might have liked a cooler color cast more.</td>', 'Love the expression and the tight crop. I might have liked a cooler color cast more.', '2009-01-01 10:09:48.000000', NULL, 1),
(5162305, 750145, 60047, '<td valign="top">Love the composition. Focus is definitely soft.</td>', 'Love the composition. Focus is definitely soft.', '2009-01-01 10:13:56.000000', NULL, 1),
(5162306, 751429, 60047, '<td valign="top">Lighting seems to be a little harsh and flattening.</td>', 'Lighting seems to be a little harsh and flattening.', '2009-01-01 10:14:36.000000', NULL, 1),
(5162310, 750207, 60047, '<td valign="top">Love his expression. I think you could crop out most of the left half of this shot and have a better submission for this challenge. The lattice makes a great BG but you really don''t need all that you have in this shot.</td>', 'Love his expression. I think you could crop out most of the left half of this shot and have a better submission for this challenge. The lattice makes a great BG but you really don''t need all that you have in this shot.', '2009-01-01 10:16:31.000000', NULL, 1),
(5162316, 750105, 60047, '<td valign="top">Interesting use of the light. I think this might benefit from cooling off the white balance a bit and easing off of the yellows. The clutter on the right side of the shot is a bit distracting.</td>', 'Interesting use of the light. I think this might benefit from cooling off the white balance a bit and easing off of the yellows. The clutter on the right side of the shot is a bit distracting.', '2009-01-01 10:19:06.000000', NULL, 1),
(5162320, 750532, 60047, '<td valign="top">Great composition and POV. Lighting is a little harsh and flattening. I wish the green watering bucket was not in the shot.</td>', 'Great composition and POV. Lighting is a little harsh and flattening. I wish the green watering bucket was not in the shot.', '2009-01-01 10:20:36.000000', NULL, 1),
(5162323, 751420, 60047, '<td valign="top">The size of the subjects are just a bit too small in this composition. The star of the photo is really the architecture rather than the elderly. With that said, this is a great street shot and fascinating to look at.</td>', 'The size of the subjects are just a bit too small in this composition. The star of the photo is really the architecture rather than the elderly. With that said, this is a great street shot and fascinating to look at.', '2009-01-01 10:23:05.000000', NULL, 1),
(5162326, 750675, 60047, '<td valign="top">What a fun idea. I wish the crown did not blend into the BG so well.</td>', 'What a fun idea. I wish the crown did not blend into the BG so well.', '2009-01-01 10:23:50.000000', NULL, 1),
(5162329, 751285, 60047, '<td valign="top">This is a great composition. I wish the focus and exposure were more clear on his face.</td>', 'This is a great composition. I wish the focus and exposure were more clear on his face.', '2009-01-01 10:25:26.000000', NULL, 1),
(5162333, 750712, 60047, '<td valign="top">Wonderful warm expression on her face. The bright light on her hair is a bit distracting.</td>', 'Wonderful warm expression on her face. The bright light on her hair is a bit distracting.', '2009-01-01 10:27:05.000000', NULL, 1),
(5162335, 750455, 60047, '<td valign="top">I love this shot. Great composition. I have the sense that you have captured him in his element.</td>', 'I love this shot. Great composition. I have the sense that you have captured him in his element.', '2009-01-01 10:28:08.000000', NULL, 1),
(5162337, 751381, 60047, '<td valign="top">Unfortunately the smoke gets lost in the composition. I think a straight black BG might have worked better.</td>', 'Unfortunately the smoke gets lost in the composition. I think a straight black BG might have worked better.', '2009-01-01 10:29:23.000000', NULL, 1),
(5162340, 750108, 60047, '<td valign="top">I love the dark tones in this but I think it could do better to be just a bit lighter to show a bit more detail on the subject. I love the clutter in this shot.</td>', 'I love the dark tones in this but I think it could do better to be just a bit lighter to show a bit more detail on the subject. I love the clutter in this shot.', '2009-01-01 10:30:53.000000', NULL, 1),
(5162342, 750801, 60047, '<td valign="top">A classic portrait. Well done.</td>', 'A classic portrait. Well done.', '2009-01-01 10:31:35.000000', NULL, 1),
(5162345, 751503, 60047, '<td valign="top">What a great expression. Nice portrait.</td>', 'What a great expression. Nice portrait.', '2009-01-01 10:32:40.000000', NULL, 1),
(5162349, 750317, 60047, '<td valign="top">Great composition. Great tight crop. Great expression. And you''ve manage difficult lighting well.</td>', 'Great composition. Great tight crop. Great expression. And you''ve manage difficult lighting well.', '2009-01-01 10:33:42.000000', NULL, 1),
(5162350, 750492, 60047, '<td valign="top">Powerful.</td>', 'Powerful.', '2009-01-01 10:34:03.000000', NULL, 1),
