(5162360, 751305, 60047, '<td valign="top">You get the "Out of the Box Thinking" prize!</td>', 'You get the "Out of the Box Thinking" prize!', '2009-01-01 10:36:20.000000', NULL, 1),
(5162382, 750912, 60047, '<td valign="top">Fascinating shot. Seems very serious. His looking at her tends to lead the eyes toward her. I think you could have completely cropped her out and had an equally fascinating image since his expression is so interesting.</td>', 'Fascinating shot. Seems very serious. His looking at her tends to lead the eyes toward her. I think you could have completely cropped her out and had an equally fascinating image since his expression is so interesting.', '2009-01-01 10:46:11.000000', NULL, 1),
