(5162391, 751404, 60047, '<td valign="top">The cool tones in this shot have me wondering if a little warmer temp on the white balance might have been more of an advantage. The lighting is a bit flat.</td>', 'The cool tones in this shot have me wondering if a little warmer temp on the white balance might have been more of an advantage. The lighting is a bit flat.', '2009-01-01 10:48:28.000000', NULL, 1),
(5162397, 751527, 60047, '<td valign="top">Very "Grandmotherly."  I think you could reduce the negative space and this would have the effect of more emphasis on the subject. Perfect focus and DOF for this shot.</td>', 'Very "Grandmotherly."  I think you could reduce the negative space and this would have the effect of more emphasis on the subject. Perfect focus and DOF for this shot.', '2009-01-01 10:50:26.000000', NULL, 1),
(5162405, 751336, 60047, '<td valign="top">More of a classic portrait pose and expression. I would have preferred him either smiling and/or looking into the camera.</td>', 'More of a classic portrait pose and expression. I would have preferred him either smiling and/or looking into the camera.', '2009-01-01 10:53:50.000000', NULL, 1),
