(5165668, 751305, 97225, '<td valign="top">Well, here''s a change of pace. I like it. 9</td>', 'Well, here''s a change of pace. I like it. 9', '2009-01-02 16:38:01.000000', NULL, 1),
(5165672, 751089, 97225, '<td valign="top">If this lady is elderly she sure wears it well!</td>', 'If this lady is elderly she sure wears it well!', '2009-01-02 16:39:52.000000', NULL, 1),
(5165673, 750934, 97225, '<td valign="top">Lovely shot. I love the viewpoint. It really makes him stand proud. 9</td>', 'Lovely shot. I love the viewpoint. It really makes him stand proud. 9', '2009-01-02 16:40:53.000000', NULL, 1),
(5165676, 750009, 97225, '<td valign="top">What a handsome old man. His eyes are so alert and intent. It is a lovely portrait.  9</td>', 'What a handsome old man. His eyes are so alert and intent. It is a lovely portrait.  9', '2009-01-02 16:44:01.000000', NULL, 1),
